import{_ as t,o,c as r,a2 as s}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Required Permissions","description":"ARM RBAC and Microsoft Graph permissions required by AzureScout.","frontmatter":{"description":"ARM RBAC and Microsoft Graph permissions required by AzureScout."},"headers":[],"relativePath":"guide/permissions.md","filePath":"guide/permissions.md"}'),a={name:"guide/permissions.md"};function i(n,e,d,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="required-permissions" tabindex="-1">Required Permissions <a class="header-anchor" href="#required-permissions" aria-label="Permalink to &quot;Required Permissions&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">This page covers inventory mode</p><p>This page describes the permission model for <strong>inventory mode</strong> (<code>Invoke-AzureScout</code> / <code>Test-AZSCPermissions</code>). <strong>Assessment mode</strong> (<code>-Assessment</code> / <code>Test-ScoutPermission</code>) uses a different, narrower model — see the note at the bottom of this page, or go straight to <a href="./../assessment/assessment-permissions.html">Assessment Permissions</a>. New here? See the <a href="./overview.html">Overview</a>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>AzureScout requires two categories of permissions:</p><ol><li><strong>ARM (Azure Resource Manager)</strong> — RBAC role assignments on subscriptions</li><li><strong>Microsoft Graph API</strong> — Application or delegated permissions for Entra ID data</li></ol><h2 id="arm-permissions" tabindex="-1">ARM Permissions <a class="header-anchor" href="#arm-permissions" aria-label="Permalink to &quot;ARM Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Scope</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Reader</code></td><td>Subscription(s), or the tenant-root management group</td><td>Enumerate resources, read properties — covers every ARM collector Scout has</td></tr></tbody></table><p><strong>One role is the whole ARM ask.</strong> Azure&#39;s <code>Reader</code> role is <code>Actions: */read</code> with an empty <code>NotActions</code> — a single wildcard over every control-plane read. There is no ARM collector in Scout that needs more than this, including roughly 130 of them that reach Azure through Azure Resource Graph (<code>Microsoft.ResourceGraph/resources/read</code> — also inside <code>Reader</code>&#39;s <code>*/read</code>, so the conclusion doesn&#39;t change, but a role list that names only the per-service actions is understating the ask by that one action).</p><div class="warning custom-block"><p class="custom-block-title">Assign Reader at management-group scope for the management-group and cross-subscription data</p><p>Subscription-scoped <code>Reader</code> silently returns an empty or flattened management-group hierarchy — no error, no warning. Assign it at the tenant-root management group if you want that data, or if you&#39;re running any assessment (assessment mode requires MG-root scope unconditionally — see <a href="./../assessment/assessment-permissions.html">Assessment Permissions</a>).</p><p>Whether Reader at root MG alone is sufficient for the <code>ManagementGroups</code> and <code>CustomRoleDefinitions</code> worksheets, or whether <code>Management Group Reader</code> is genuinely additional, is <strong>unresolved</strong> — do not grant <code>Management Group Reader</code> on the strength of this page alone. See <a href="./troubleshooting.html">Troubleshooting</a> if those worksheets come back empty.</p></div><div class="danger custom-block"><p class="custom-block-title">Do not grant these three roles — they were removed from the ask</p><p><code>Security Reader</code>, <code>Monitoring Reader</code>, and <code>Cost Management Reader</code> (all <strong>Azure RBAC</strong> roles, not the Entra roles of the same name) used to be listed here as optional extras. They are not strict subsets of <code>Reader</code> — the precise statement is narrower: <strong>none of them grants anything Scout calls that <code>Reader</code> does not already grant.</strong></p><ul><li><strong><code>Monitoring Reader</code></strong> additionally grants <code>Microsoft.Support/*</code>, which includes support-ticket <strong>creation</strong> — a write, in a tool sold as read-only.</li><li><strong><code>Cost Management Reader</code></strong> carries the identical <code>Microsoft.Support/*</code>.</li><li><strong>Azure RBAC <code>Security Reader</code></strong> additionally grants five IoT Defender <code>/action</code> permissions, one of which downloads a password-reset file. Scout calls none of them. (The <strong>Entra</strong><code>Security Reader</code> role is unrelated and genuinely required for four Identity collectors — see the Graph table below.)</li></ul><p>The pre-flight checker no longer asks for any of the three, and <code>Test-AZSCPermissions</code> no longer reports them as missing.</p></div><div class="tip custom-block"><p class="custom-block-title">Key Vault secrets, keys and certificates never need a data-plane grant</p><p><code>KeyVaultSecrets</code> and <code>KeyVaultKeys</code> (AB#6822) read <code>Microsoft.KeyVault/vaults/secrets</code> and <code>.../keys</code> — <strong>ARM control-plane list operations</strong> that return metadata only: id, <code>contentType</code>, and the <code>attributes</code> block (<code>enabled</code>, <code>exp</code>, <code>nbf</code>, <code>created</code>, <code>updated</code>). <code>Reader</code> on the vault is sufficient; reading a secret&#39;s or key&#39;s <strong>value</strong> is a separate data-plane operation against <code>&lt;vault&gt;.vault.azure.net</code> that needs a Key Vault access policy or data-plane RBAC role, and Scout never makes that call. A Key Vault certificate has no ARM list endpoint of its own — it is materialised as a secret whose <code>contentType</code> is <code>application/x-pkcs12</code> or <code>application/x-pem-file</code>, and that secret&#39;s <code>attributes.exp</code> <strong>is</strong> the certificate&#39;s expiry, so certificate expiry is already present in the <code>KeyVaultSecrets</code> worksheet&#39;s <code>Kind</code>/<code>Expires</code> columns rather than a separate collector. See <code>src/collect/Get-ScoutArmChildResource.ps1</code> for the exact calls.</p></div><div class="tip custom-block"><p class="custom-block-title">Cost data is not gated on a role at all</p><p><code>Microsoft.CostManagement/query/read</code> is inside <code>Reader</code>&#39;s <code>*/read</code>. If cost data still comes back empty with <code>Reader</code> assigned, the cause is a <strong>billing setting</strong>, not a permission: EA <strong>&quot;AO view charges&quot;</strong> or MCA <strong>&quot;Azure charges&quot;</strong> (the current name; older documentation calls it &quot;Allow Azure subscription users to view and optimize costs&quot;). Only an Enterprise Administrator (EA) or a <strong>Billing Profile Owner</strong> (MCA) can enable it — no Azure RBAC role, including <code>Cost Management Reader</code>, substitutes for it. See <a href="./troubleshooting.html">Troubleshooting</a>.</p></div><p>The pre-flight checker validates:</p><ul><li><strong>Subscription Enumeration</strong> — Can <code>Get-AzSubscription</code> return at least one subscription? (Fail if not)</li><li><strong>Role Assignment Read</strong> — Can <code>Get-AzRoleAssignment</code> read <code>Reader</code> on each target subscription? (Fail per subscription if <code>Reader</code> is missing there — <code>Reader</code> is the whole ARM ask, so there is no separate &quot;optional role missing&quot; Warn state any more)</li></ul><h2 id="microsoft-graph-permissions" tabindex="-1">Microsoft Graph Permissions <a class="header-anchor" href="#microsoft-graph-permissions" aria-label="Permalink to &quot;Microsoft Graph Permissions&quot;">​</a></h2><p>These are the Microsoft Graph <strong>application</strong> permissions a service principal needs for Entra ID inventory (<code>-Scope All</code> or <code>-Scope EntraOnly</code>). They are derived directly from the queries Scout&#39;s Entra collectors actually issue — not a hand-maintained list — so a permission with no consumer is called out rather than requested:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Organization.Read.All</code></td><td>Application or Delegated</td><td>Read tenant organization details</td></tr><tr><td><code>User.Read.All</code></td><td>Application or Delegated</td><td>Read all user profiles</td></tr><tr><td><code>Group.Read.All</code></td><td>Application or Delegated</td><td>Read all groups and memberships</td></tr><tr><td><code>Application.Read.All</code></td><td>Application or Delegated</td><td>Read all app registrations and service principals</td></tr><tr><td><code>RoleManagement.Read.Directory</code></td><td>Application or Delegated</td><td>Read directory roles and PIM role assignments</td></tr><tr><td><code>Policy.Read.All</code></td><td>Application or Delegated</td><td>Read conditional access policies, named locations, authorization policy, cross-tenant access policy</td></tr><tr><td><code>AdministrativeUnit.Read.All</code></td><td>Application or Delegated</td><td>Read administrative units</td></tr><tr><td><code>Domain.Read.All</code></td><td>Application or Delegated</td><td>Read verified domains</td></tr><tr><td><code>IdentityRiskyUser.Read.All</code></td><td>Application or Delegated</td><td>Read risky-user signals — <strong>also requires an Entra ID P2 licence</strong>; a P1 tenant with the permission granted still returns nothing</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title"><code>IdentityProvider.Read.All</code> is queried but no collector reads the result — do not grant it</p><p>Scout&#39;s pre-flight now derives criticality from which collectors actually consume a permission, not from a fixed list. <code>IdentityProvider.Read.All</code> still shows up as a probe because the query runs, but nothing downstream reads its output, so the pre-flight reports it <code>Warn</code> — &quot;queried but NO collector reads the result. Do not grant it.&quot; — rather than asking for it. <code>AuditLog.Read.All</code> was removed from the ask entirely for the same reason: no collector ever consumed sign-in logs.</p></div><p>If you&#39;re signing in as a <strong>user</strong> instead of a service principal, the equivalent least-privilege grant is two Entra <strong>directory roles</strong> — <code>Directory Readers</code> + Entra <code>Security Reader</code> — not the application permissions above. Azure RBAC, Entra directory roles, and Graph application permissions are three separate systems with different scoping and approvers; pick the directory roles or the app permissions based on whether Scout runs as a user or a service principal, don&#39;t mix them. <code>Directory Readers</code> + <code>Security Reader</code> covers 14 of the 15 Entra collectors; the fifteenth, <code>CrossTenantAccess</code>, needs <code>Security Administrator</code>, <code>Tenant Governance Administrator</code>, or <code>Global Reader</code> — evaluate the first two before reaching for <code>Global Reader</code>, which Microsoft classifies as a privileged role. See <a href="./../assessment/assessment-permissions.html">Assessment Permissions</a>.</p><h2 id="pre-flight-validation" tabindex="-1">Pre-flight Validation <a class="header-anchor" href="#pre-flight-validation" aria-label="Permalink to &quot;Pre-flight Validation&quot;">​</a></h2><p>The <code>Test-AZSCPermissions</code> function runs automatically before extraction (unless <code>-SkipPermissionCheck</code> is set):</p><table tabindex="0"><thead><tr><th>Check</th><th>Severity</th><th>Behavior</th></tr></thead><tbody><tr><td>ARM: Subscription Enumeration</td><td><strong>Fail</strong></td><td>Stops ARM extraction if no subscriptions accessible</td></tr><tr><td>ARM: Role Assignment Read (per subscription)</td><td><strong>Fail</strong></td><td>That subscription&#39;s inventory is incomplete without <code>Reader</code></td></tr><tr><td>Graph: each permission with a consumer</td><td><strong>Fail</strong></td><td>Names the exact collectors that will come back empty, and the permission to grant</td></tr><tr><td>Graph: each permission with no consumer</td><td><strong>Warn</strong></td><td>Reports it as unused — &quot;do not grant&quot; — rather than requesting it</td></tr></tbody></table><p><strong>The output is a per-collector impact table, not a bare READY / PARTIAL / INSUFFICIENT verdict.</strong> Criticality is derived from which collectors consume which permission, so there is no separate hardcoded list of &quot;critical&quot; permissions to fall out of date. A denied Graph permission also reaches PowerShell&#39;s warning stream now, not only a coloured console write — so an automated caller (CI, a scheduled Automation Account run) can detect and act on it, not just a human watching the console. See <a href="./troubleshooting.html">Troubleshooting</a> for what to do with a <code>Fail</code>.</p><h2 id="scope-based-gating" tabindex="-1">Scope-Based Gating <a class="header-anchor" href="#scope-based-gating" aria-label="Permalink to &quot;Scope-Based Gating&quot;">​</a></h2><p>Permission checks respect the <code>-Scope</code> parameter:</p><ul><li><code>ArmOnly</code> — Only ARM checks run (Graph checks are skipped entirely)</li><li><code>EntraOnly</code> — Only Graph checks run (ARM checks are skipped entirely)</li><li><code>All</code> — Both ARM and Graph checks run</li></ul><h2 id="remediation" tabindex="-1">Remediation <a class="header-anchor" href="#remediation" aria-label="Permalink to &quot;Remediation&quot;">​</a></h2><p>If the permission checker reports failures:</p><ol><li>For ARM: Ensure <code>Reader</code> role is assigned on target subscriptions</li><li>For Graph: Grant the required Microsoft Graph API permissions to your app registration or user account</li><li>Re-run with the appropriate credentials</li></ol><div class="warning custom-block"><p class="custom-block-title">Verification status</p><p>This page is documentation analysis backed by Microsoft&#39;s published role and permission references, not a tested result. No run has been performed against a <code>Reader</code>-only principal (or the Entra/Graph minimum-privilege grants above) to confirm every collector still returns data. The reasoning is sound and Microsoft-doc-backed, but treat it as <strong>probable, not proven</strong> until a live comparison run exists.</p></div><h2 id="a-different-narrower-model-for-the-caf-waf-assessment-platform" tabindex="-1">A different, narrower model for the CAF/WAF assessment platform <a class="header-anchor" href="#a-different-narrower-model-for-the-caf-waf-assessment-platform" aria-label="Permalink to &quot;A different, narrower model for the CAF/WAF assessment platform&quot;">​</a></h2><p>Everything above is the <strong>inventory mode</strong> permission model (<code>Invoke-AzureScout</code> / <code>Test-AZSCPermissions</code>). <strong>Assessment mode</strong> (<code>-Assessment</code> / <code>Test-ScoutPermission</code>) uses a different, narrower model — do not conflate the two:</p><table tabindex="0"><thead><tr><th></th><th>Inventory mode (<code>Test-AZSCPermissions</code>)</th><th>Assessment mode (<code>Test-ScoutPermission</code>)</th></tr></thead><tbody><tr><td>ARM scope</td><td><code>Reader</code> on each target <strong>subscription</strong></td><td><code>Reader</code> at the <strong>tenant-root management group</strong></td></tr><tr><td>Graph</td><td>Up to 9 permissions, required for <code>-Scope All</code>/<code>EntraOnly</code></td><td>Not required by any assessment out of the box — governance data (<code>LandingZone</code>, <code>Management</code>, <code>Identity</code>, <code>Governance</code>, <code>Policy</code>) is collected natively via ARM/Resource Graph. 4 Graph permissions apply <strong>only</strong> if you opt one of those 5 into the legacy <code>AzGovViz</code> ingestor instead</td></tr><tr><td>Live-validated?</td><td>Yes — both ARM and Graph checks call live endpoints</td><td>ARM check is live; the 4 Graph permissions are listed as an <strong>unverified checklist</strong> (<code>Ok = $null</code>), not actually tested</td></tr></tbody></table><p>Full matrix (every assessment, minimum RBAC, which need Graph, and the <code>PrivilegedAccess.Read.AzureResources</code> / Entra P2 nuance): <a href="./../assessment/assessment-permissions.html">Auth &amp; permissions per scan type</a>.</p>',34)])])}const m=t(a,[["render",i]]);export{u as __pageData,m as default};
